arguments.command:
curl -s https://ollama.com/api/tags | python3 -c "
import sys, json
data = json.load(sys.stdin)
models = ['qwen3:8b', 'qwen3:4b', 'deepseek-r1:7b', 'deepseek-r1:8b', 'mistral:7b']
for m in models:
